+  ];
+  const pointAt = (t) => {
+    const f = ((t % 1) + 1) % 1 * path.length, i = Math.floor(f), u = f - i;
+    const a = path[(i - 1 + path.length) % path.length], b = path[i], c = path[(i + 1) % path.length], d = path[(i + 2) % path.length];
