+    c.fillStyle='rgba(221,202,119,.13)';for(let i=0;i<45;i++){let x=(i*173+39)%w,y=(i*97+31)%h;c.fillRect(x,y,3,3);}
+    c.beginPath();for(let i=0;i<=360;i++){let p=pointAt(i/360);if(!i)c.moveTo(p.x,p.y);else c.lineTo(p.x,p.y);}c.closePath();c.lineCap='round';c.lineJoin='round';c.strokeStyle='#d8cf9e';c.lineWidth=112;c.stroke();c.strokeStyle='#303a38';c.lineWidth=94;c.stroke();c.strokeStyle='rgba(238,222,172,.8)';c.lineWidth=2;c.setLineDash([16,19]);c.stroke();c.setLineDash([]);
+    for(let i=0;i<12;i++){let p=pointAt((i+.5)/12);let ox=Math.cos(p.angle+Math.PI/2)*76,oy=Math.sin(p.angle+Math.PI/2)*76;c.fillStyle=i%2?'#344139':'#e1d9b4';c.fillRect(p.x+ox-3,p.y+oy-3,7,7);}
+    const start=pointAt(0);c.save();c.translate(start.x,start.y);c.rotate(start.angle);for(let i=0;i<12;i++){c.fillStyle=(i%2===Math.floor(i/2)%2)?'#f4edcf':'#252e2c';c.fillRect(-3,-47+i*8,8,8);}c.restore();
+    // low-poly hills and trees establish an original, readable pixel-art setting
+    c.fillStyle='#344f3d';for(let i=0;i<13;i++){let x=(i*89+30)%950,y=(i*127+44)%560;if(distanceToRoad(x,y)>100){c.fillRect(x,y,8,7);c.fillRect(x+2,y-5,4,5);}}
+  }
+  function distanceToRoad(x,y){let d=1e9;for(let i=0;i<180;i++){const p=pointAt(i/180);d=Math.min(d,Math.hypot(p.x-x,p.y-y));}return d;}
+  function drawCar(car){let p=pointAt(car.progress),side=Math.cos(p.angle+Math.PI/2)*car.lane*46,sideY=Math.sin(p.angle+Math.PI/2)*car.lane*46;ctx.save();ctx.translate(p.x+side,p.y+sideY);ctx.rotate(p.angle);ctx.fillStyle='rgba(14,22,20,.4)';ctx.fillRect(-10,-13,22,29);ctx.fillStyle='#202a28';ctx.fillRect(-10,-11,4,8);ctx.fillRect(6,-11,4,8);ctx.fillRect(-10,6,4,8);ctx.fillRect(6,6,4,8);ctx.fillStyle=car.color;ctx.fillRect(-8,-14,16,29);ctx.fillRect(-6,-19,12,9);ctx.fillStyle='#283b3b';ctx.fillRect(-5,-8,10,8);ctx.fillStyle='rgba(255,255,220,.6)';ctx.fillRect(-6,-16,3,2);ctx.fillRect(3,-16,3,2);ctx.fillStyle='#ef6654';ctx.fillRect(-6,12,3,2);ctx.fillRect(3,12,3,2);if(car.id===0){ctx.strokeStyle='#fff0a6';ctx.lineWidth=2;ctx.strokeRect(-10,-20,20,41);}ctx.restore();}
+  function renderMini(){mctx.clearRect(0,0,120,88);mctx.fillStyle='#16342c';mctx.fillRect(0,0,120,88);mctx.beginPath();for(let i=0;i<=180;i++){let p=pointAt(i/180),x=p.x/960*112+4,y=p.y/600*80+4;if(!i)mctx.moveTo(x,y);else mctx.lineTo(x,y);}mctx.closePath();mctx.strokeStyle='#d2c895';mctx.lineWidth=12;mctx.stroke();mctx.strokeStyle='#414c41';mctx.lineWidth=8;mctx.stroke();cars.forEach(c=>{let p=pointAt(c.progress);mctx.fillStyle=c.color;mctx.fillRect(p.x/960*112+2,p.y/600*80+2,5,5);});}
+  function loop(now){if(state!=='racing'&&state!=='countdown')return;let dt=Math.min(.04,(now-last)/1000);last=now;
