+  for(const [id,key] of [['left','left'],['right','right'],['accelerate','go'],['brake','brake']]){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();held[key]=true;el.setPointerCapture(e.pointerId);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,()=>held[key]=false);}
+  window.addEventListener('keydown',e=>{const map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'go',w:'go',' ':'go',ArrowDown:'brake',s:'brake'};if(e.key==='Escape'&&state==='racing'){pause();return;}if(map[e.key]){held[map[e.key]]=true;e.preventDefault();}});window.addEventListener('keyup',e=>{const map={ArrowLeft:'left',a:'left',ArrowRight:'right',d:'right',ArrowUp:'go',w:'go',' ':'go',ArrowDown:'brake',s:'brake'};if(map[e.key])held[map[e.key]]=false;});
+  updateWallet();if(!data.name)setTimeout(namePrompt,500);
+})();
